package com.regcode.collection;
import org.json.*;import org.junit.Test;import static org.junit.Assert.*;import java.util.*;import java.io.*;
public class WorkerStoreTest {
 @Test public void externalClassificationUsesWebsiteWithoutKnownCodes()throws Exception{try(QueueStoreTest.Jdbc db=new QueueStoreTest.Jdbc(":memory:")){WorkerStore w=new WorkerStore(db);w.start(new JSONObject().put("mode","external"),profile(1),1);assertEquals("internal",w.capture("https://www.nz315.cn/trace?code="+A,profile(1),2).getString("classification"));assertEquals("external",w.capture("https://vendor.example/trace?code="+B,profile(1),3).getString("classification"));assertEquals("unparsed",w.capture(A,profile(1),4).getString("classification"));}}
 static final String A="00000000000000000000000000000001",B="00000000000000000000000000000002",POOL=UUID.randomUUID().toString();
 static JSONObject profile(int id){return new JSONObject().put("identity",new JSONObject().put("id",id).put("name","worker"+id).put("deviceId",10)).put("grantId","grant"+id);}
 static JSONObject context(){return new JSONObject().put("mode","production").put("productId",1).put("poolId",POOL).put("batchNo","A").put("produceDate","2026-10-12").put("expireDate","2027-10-12");}
 static WorkerStore ready(QueueStoreTest.Jdbc db)throws Exception{WorkerStore w=new WorkerStore(db);String cache="cache1";w.stage(cache,"products",new JSONArray().put(new JSONObject().put("id",1).put("name","product")));w.stage(cache,"pools",new JSONArray().put(new JSONObject().put("id",POOL).put("product_id",1).put("state","ready")));JSONArray codes=new JSONArray();for(String code:new String[]{A,B})codes.put(new JSONObject().put("pool_id",POOL).put("code",code).put("state","reserved"));w.stage(cache,"codes",codes);w.commitCache(new JSONObject().put("id",cache).put("expiresAt",Long.MAX_VALUE).put("products",1).put("pools",1).put("codes",2));return w;}
 @Test public void dynamicWorkersShareBatchButKeepImmutableIdentity()throws Exception{try(QueueStoreTest.Jdbc db=new QueueStoreTest.Jdbc(":memory:")){WorkerStore w=ready(db);JSONObject r=w.start(context(),profile(1),System.currentTimeMillis());JSONObject a=w.capture(A,profile(1),System.currentTimeMillis());w.handover(1);w.start(context(),profile(2),System.currentTimeMillis());JSONObject b=w.capture(B,profile(2),System.currentTimeMillis());JSONArray sessions=w.sessions();assertEquals(2,sessions.length());assertEquals(1,sessions.getJSONObject(0).getLong("user_id"));assertEquals(2,sessions.getJSONObject(1).getLong("user_id"));assertEquals(r.getString("id"),sessions.getJSONObject(1).getString("run_id"));assertEquals("duplicate",w.capture("different?47="+A,profile(2),System.currentTimeMillis()).getString("kind"));assertEquals(2,w.snapshot(2).getJSONObject("counts").getInt("collected"));}}
 @Test public void invalidAndDuplicateCommitBeforeAcknowledgement()throws Exception{try(QueueStoreTest.Jdbc db=new QueueStoreTest.Jdbc(":memory:")){WorkerStore w=ready(db);w.start(context(),profile(1),1);w.capture("half?i="+A,profile(1),2);assertEquals("duplicate",w.capture("other?x="+A,profile(1),3).getString("kind"));assertEquals("invalid",w.capture("short",profile(1),4).getString("kind"));assertEquals(3,w.snapshot(1).getLong("allWaiting"));}}
 @Test public void incompleteNewCacheDoesNotReplaceOldOrBatchManifest()throws Exception{try(QueueStoreTest.Jdbc db=new QueueStoreTest.Jdbc(":memory:")){WorkerStore w=ready(db);w.start(context(),profile(1),1);w.stage("bad","products",new JSONArray().put(new JSONObject().put("id",99)));assertThrows(Exception.class,()->w.commitCache(new JSONObject().put("id","bad").put("products",2).put("pools",0).put("codes",0)));assertEquals(1,w.catalog("products").getJSONObject(0).getInt("id"));assertEquals("valid",w.capture(A,profile(1),2).getString("kind"));}}
 @Test public void finishedPoolCannotBeReusedAndOtherOfflineBatchCanQueue()throws Exception{try(QueueStoreTest.Jdbc db=new QueueStoreTest.Jdbc(":memory:")){WorkerStore w=ready(db);w.start(context(),profile(1),1);w.capture(A,profile(1),2);w.finish(1);assertThrows(Exception.class,()->w.start(context(),profile(1),3));w.start(new JSONObject().put("mode","external").put("name","external"),profile(1),4);w.capture("https://vendor.example/?id=abc",profile(1),5);assertEquals(2,w.sessions().length());assertEquals(2,w.snapshot(1).getLong("allWaiting"));}}
 @Test public void existingBatchMetadataCannotChangeAtHandover()throws Exception{try(QueueStoreTest.Jdbc db=new QueueStoreTest.Jdbc(":memory:")){WorkerStore w=ready(db);w.start(context(),profile(1),1);w.capture(A,profile(1),2);w.handover(1);assertThrows(Exception.class,()->w.start(context().put("batchNo","B"),profile(2),3));w.start(context(),profile(2),3);assertEquals("A",w.currentRun().getJSONObject("context").getString("batchNo"));}}
 @Test public void malformedReceiptDoesNotRemoveEventAndBackupFiltersWorker()throws Exception{try(QueueStoreTest.Jdbc db=new QueueStoreTest.Jdbc(":memory:")){WorkerStore w=ready(db);w.start(context(),profile(1),1);JSONObject a=w.capture(A,profile(1),2);w.handover(1);w.start(context(),profile(2),3);w.capture(B,profile(2),4);String sid=w.sessions().getJSONObject(0).getString("id");JSONObject receipt=new JSONObject().put("eventId",a.getString("eventId")).put("sequence",1).put("code",B).put("state","saved");assertThrows(Exception.class,()->w.acknowledge(sid,new JSONObject().put("sessionId",sid).put("receipts",new JSONArray().put(receipt))));assertEquals(1,w.pending(sid,20).length());receipt.put("code",A);w.acknowledge(sid,new JSONObject().put("sessionId",sid).put("receipts",new JSONArray().put(receipt)));assertEquals(0,w.pending(sid,20).length());ByteArrayOutputStream out=new ByteArrayOutputStream();w.backup(out,1);JSONObject backup=new JSONObject(out.toString("UTF-8"));assertEquals(1,backup.getJSONArray("events").length());assertEquals(A,backup.getJSONArray("events").getJSONObject(0).getString("code"));assertFalse(out.toString("UTF-8").contains("grant"));}}
 @Test public void externalDedupUsesCodeOtherwiseRawWithinBatch()throws Exception{try(QueueStoreTest.Jdbc db=new QueueStoreTest.Jdbc(":memory:")){WorkerStore w=new WorkerStore(db);w.start(new JSONObject().put("mode","external"),profile(1),1);assertEquals("valid",w.capture("x?i="+A,profile(1),2).getString("kind"));assertEquals("duplicate",w.capture("y?47="+A,profile(1),3).getString("kind"));assertEquals("valid",w.capture("https://foreign/?a=abc",profile(1),4).getString("kind"));assertEquals("duplicate",w.capture("https://foreign/?a=abc",profile(1),5).getString("kind"));}}
 @Test public void databaseReopenRestoresSeveralQueuesAndExactEventIds()throws Exception{java.nio.file.Path path=java.nio.file.Files.createTempFile("worker-queue-",".sqlite");String eventId;try{try(QueueStoreTest.Jdbc db=new QueueStoreTest.Jdbc(path.toString())){WorkerStore w=ready(db);w.start(context(),profile(1),1);eventId=w.capture(A,profile(1),2).getString("eventId");w.finish(1);w.start(new JSONObject().put("mode","external"),profile(2),3);w.capture("abc",profile(2),4);}try(QueueStoreTest.Jdbc db=new QueueStoreTest.Jdbc(path.toString())){WorkerStore w=new WorkerStore(db);assertEquals(2,w.sessions().length());String sid=w.sessions().getJSONObject(0).getString("id");assertEquals(eventId,w.pending(sid,20).getJSONObject(0).getString("eventId"));assertEquals("closing",w.sessions().getJSONObject(0).getString("state"));}}finally{java.nio.file.Files.deleteIfExists(path);}}
 @Test public void failedCommitRollsBackSequenceAndFastScanPersistsAll()throws Exception{try(QueueStoreTest.Jdbc db=new QueueStoreTest.Jdbc(":memory:")){WorkerStore w=ready(db);w.start(context(),profile(1),1);db.exec("CREATE TRIGGER worker_fault BEFORE UPDATE OF next_seq ON ww_session BEGIN SELECT RAISE(ABORT,'full');END");assertThrows(Exception.class,()->w.capture(A,profile(1),2));assertEquals(0,w.snapshot(1).getLong("allWaiting"));db.exec("DROP TRIGGER worker_fault");for(int i=0;i<1000;i++)w.capture(i%2==0?A:B,profile(1),3+i);assertEquals(1000,w.snapshot(1).getLong("allWaiting"));assertEquals(2,w.snapshot(1).getJSONObject("counts").getInt("collected"));}}
 @Test public void cloudConflictBecomesExceptionAndRescanStillDeduplicates()throws Exception{try(QueueStoreTest.Jdbc db=new QueueStoreTest.Jdbc(":memory:")){WorkerStore w=ready(db);w.start(context(),profile(1),1);JSONObject event=w.capture(A,profile(1),2);String sid=w.sessions().getJSONObject(0).getString("id");w.acknowledge(sid,new JSONObject().put("sessionId",sid).put("receipts",new JSONArray().put(new JSONObject().put("eventId",event.getString("eventId")).put("sequence",1).put("code",A).put("state","exception").put("reason","云端冲突"))));assertEquals(0,w.snapshot(1).getJSONObject("counts").getInt("collected"));assertEquals(1,w.snapshot(1).getJSONObject("counts").getInt("exceptions"));assertEquals("duplicate",w.capture("different?47="+A,profile(1),3).getString("kind"));}}
 @Test public void ownershipCannotChangeUntilRunCompletionEvenWithNoWaitingEvents()throws Exception{try(QueueStoreTest.Jdbc db=new QueueStoreTest.Jdbc(":memory:")){WorkerStore w=ready(db);assertFalse(w.hasUnconfirmedWork());JSONObject run=w.start(context(),profile(1),1);assertEquals(0,w.snapshot(1).getLong("allWaiting"));assertTrue(w.hasUnconfirmedWork());w.handover(1);assertTrue(w.hasUnconfirmedWork());w.resume(run.getString("id"),profile(1),2);w.finish(1);for(int i=0;i<w.sessions().length();){JSONObject session=w.sessions().getJSONObject(i);w.completed(session.getString("id"),0);}assertEquals(0,w.sessions().length());assertTrue(w.hasUnconfirmedWork());assertEquals(1,w.closingRuns().length());w.runDone(run.getString("id"));assertFalse(w.hasUnconfirmedWork());}}
}
